return ['x-generator'=>'GlotPress/4.1.0','translation-revision-date'=>'2026-09-28 23:18:07+0000','plural-forms'=>'nplurals=3; plural=(n % 10 == 1 && n % 100 != 11) ? 0 : ((n % 10 >= 2 && n % 10 <= 4 && (n % 100 < 12 || n % 100 > 14)) ? 1 : 2);','project-id-version'=>'Plugins - WooPayments: Integrated WooCommerce Payments - Stable (latest release)','language'=>'sr_RS','messages'=>['Select your currency'=>'Изаберите своју валуту','Refund this payment'=>'Рефундирај ово плаћање','Reported reason: %s'=>'Пријављени разлог: %s','The card issuer flagged this payment as likely fraudulent. Refunding it now can prevent a dispute.'=>'Издавалац картице означио је ово плаћање као вероватну превару. Рефундирање сада може спречити спор.','This payment was refunded or disputed, so the warning is no longer actionable.'=>'Ово плаћање је рефундирано или оспорено, па по упозорењу више није могуће поступити.','Early fraud warning'=>'Рано упозорење о превари','Early fraud warning resolved'=>'Рано упозорење о превари решено','Triggered risk filters:'=>'Покренути филтери ризика:','Unauthorized use of card'=>'Неовлашћено коришћење картице','Made with stolen card'=>'Извршено украденом картицом','Made with lost card'=>'Извршено изгубљеном картицом','Fraudulent card application'=>'Лажни захтев за картицу','Card never received'=>'Картица никад није примљена','Made with counterfeit card'=>'Извршено фалсификованом картицом','Payment has received an early fraud warning with reason "%1$s". <refund>Refunding the payment now</refund> can prevent a dispute. See <a>payment details</a> for more information.'=>'Плаћање је добило рано упозорење о превари са разлогом „%1$s“. <refund>Рефундирање плаћања сада</refund> може спречити спор. Погледајте <a>детаље плаћања</a> за више података.','Payment has received an early fraud warning. <refund>Refunding the payment now</refund> can prevent a dispute. See <a>payment details</a> for more information.'=>'Плаћање је добило рано упозорење о превари. <refund>Рефундирање плаћања сада</refund> може спречити спор. Погледајте <a>детаље плаћања</a> за више података.','&#x26D4; A payment of %1$s was <strong>held for review</strong> by the following risk filters:<br>%2$s<br><br><a>View more details</a>.'=>'&#x26D4; Плаћање од %1$s <strong>задржали су на прегледу</strong> следећи филтери ризика:<br>%2$s<br><br><a>Погледајте више детаља</a>.','&#x1F6AB; A payment of %1$s was <strong>blocked</strong> by the following risk filters:<br>%2$s<br><br><a>View more details</a>.'=>'&#x1F6AB; Плаћање од %1$s <strong>блокирали</strong> су следећи филтери ризика:<br>%2$s<br><br><a>Погледајте више детаља</a>.','The early fraud warning received for this payment is no longer actionable, because the payment was refunded or disputed. See <a>payment details</a> for more information.'=>'По раном упозорењу о превари примљеном за ово плаћање више није могуће поступити, јер је плаћање рефундирано или оспорено. Погледајте <a>детаље плаћања</a> за више података.','The order was not marked as completed because it has already been fully refunded.'=>'Поруџбина није означена као завршена јер је већ у потпуности рефундирана.','WooPayments: detected and prevented a second payment for this order, which had already been paid.'=>'WooPayments: откривено је и спречено друго плаћање за ову поруџбину, која је већ била плаћена.','The order was not marked as completed because %d other dispute on this payment is still open.'=>'Поруџбина није означена као завршена јер је %d други спор за ово плаћање још отворен.' . "\0" . 'Поруџбина није означена као завршена јер су %d друга спора за ово плаћање још отворена.' . "\0" . 'Поруџбина није означена као завршена јер је %d других спорова за ово плаћање још отворено.','Recovered missing subscription payment method token from the parent order.'=>'Опорављен је недостајући жетон начина плаћања претплате из родитељске поруџбине.','The saved payment method for this subscription was missing, so WooPayments restored %s from the original order to complete the renewal.'=>'Сачувани начин плаћања за ову претплату је недостајао, па је WooPayments вратио %s из изворне поруџбине да би довршио обнову.','WooPayments updated the subscription payment method token from token #%1$d to #%2$d after receiving a successful renewal payment webhook.'=>'WooPayments је ажурирао жетон начина плаћања претплате са жетона бр. %1$d на бр. %2$d после пријема webhook-а о успешном плаћању обнове.','(Dispute ID: %s)'=>'(ИБ спора: %s)','Unable to save payment method for subscription. The order customer could not be found.'=>'Није могуће сачувати начин плаћања за претплату. Купац поруџбине није пронађен.','Give customers a direct way to reach you from their order emails to handle issues quickly.'=>'Пружите купцима директан начин да вам се обрате из е-порука о поруџбинама како би се проблеми брзо решили.','Make sure your business name appears clearly on customer bank statements to prevent confusion.'=>'Уверите се да се име вашег пословања јасно приказује на изводима банке купаца да бисте спречили забуну.','Customer support contact linked in order emails'=>'Контакт подршке за купце повезан у е-порукама о поруџбинама','Recognizable statement descriptor'=>'Препознатљив опис на изводу','Looks good'=>'Изгледа добро','Your statement descriptor will show up on your customers\' bank statements. Does it clearly identify your store?'=>'Ваш опис на изводу приказаће се на изводима банке ваших купаца. Да ли јасно означава вашу продавницу?','Add a T&C link at checkout so customers acknowledge your policies before completing a purchase.'=>'Додајте везу ка условима и одредбама при плаћању да би купци потврдили ваше политике пре довршавања куповине.','Fix it'=>'Поправи','Terms & conditions linked at checkout'=>'Услови и одредбе повезани при плаћању','Publish a refund policy so customers can resolve issues with you before filing a dispute.'=>'Објавите политику рефундације да би купци могли да реше проблеме са вама пре подношења спора.','Refund policy page published'=>'Страница политике рефундације је објављена','file_contents must be base64-encoded.'=>'file_contents мора бити кодиран у base64.','The file exceeds the %d-byte dispute-evidence size limit.'=>'Датотека премашује ограничење величине доказа за спор од %d бајтова.','file_type must be one of application/pdf, image/jpeg, or image/png.'=>'file_type мора бити једно од application/pdf, image/jpeg или image/png.','file_name, file_type, and file_contents are all required to upload a file.'=>'file_name, file_type и file_contents су сви обавезни за отпремање датотеке.','Base64-encoded file contents. The decoded size must not exceed the dispute-evidence size limit.'=>'Садржај датотеке кодиран у base64. Декодирана величина не сме премашити ограничење величине доказа за спор.','File MIME type. One of application/pdf, image/jpeg, or image/png.'=>'MIME врста датотеке. Једно од application/pdf, image/jpeg или image/png.','Upload a document (PDF, PNG, or JPEG) to use as dispute evidence. Returns a file object whose id can be passed to the document fields of woocommerce-payments/submit-dispute-evidence.'=>'Отпремите документ (PDF, PNG или JPEG) који ће се користити као доказ у спору. Враћа објекат датотеке чији се id може проследити пољима документа у woocommerce-payments/submit-dispute-evidence.','File name including extension (e.g. receipt.pdf).'=>'Име датотеке са наставком (нпр. receipt.pdf).','Upload dispute evidence file'=>'Отпреми датотеку доказа за спор','Metadata values must be strings of 500 characters or fewer.'=>'Вредности метаподатака морају бити ниске од 500 знакова или мање.','Metadata keys must be strings of 40 characters or fewer.'=>'Кључеви метаподатака морају бити ниске од 40 знакова или мање.','Metadata may not contain more than 10 keys.'=>'Метаподаци не смеју садржати више од 10 кључева.','Evidence fields. Text fields take free text; document fields take the ID of a file uploaded via woocommerce-payments/upload-dispute-evidence-file (not raw file contents).'=>'Поља доказа. Текстуална поља примају слободан текст; поља документа примају ИБ датотеке отпремљене преко woocommerce-payments/upload-dispute-evidence-file (не сирови садржај датотеке).','Whether to submit to the card network (irreversible). Default false stages a draft.'=>'Да ли послати мрежи картица (неповратно). Подразумевана вредност false припрема нацрт.','A dispute_id is required to submit evidence.'=>'За слање доказа потребан је dispute_id.','Stage or submit evidence for a dispute. With submit=false (default) the evidence is saved as a draft you can revise; with submit=true it is sent to the card network and cannot be changed.'=>'Припремите или пошаљите доказе за спор. Уз submit=false (подразумевано) доказ се чува као нацрт који можете мењати; уз submit=true шаље се мрежи картица и не може се мењати.','Optional metadata to attach to the dispute. Maximum 10 keys; keys up to 40 characters; values up to 500 characters.'=>'Необавезни метаподаци за придруживање спору. Највише 10 кључева; кључеви до 40 знакова; вредности до 500 знакова.','Submit dispute evidence'=>'Пошаљи доказе за спор','Any additional supporting document.'=>'Било који додатни пратећи документ.','%s Provide the ID of a file uploaded via woocommerce-payments/upload-dispute-evidence-file, not raw file contents.'=>'%s Наведите ИБ датотеке отпремљене преко woocommerce-payments/upload-dispute-evidence-file, а не сирови садржај датотеке.','Your cancellation policy as shown to the customer.'=>'Ваша политика отказивања онако како је приказана купцу.','Proof the service was provided to the customer.'=>'Доказ да је услуга пружена купцу.','Proof the product was delivered (e.g. signed delivery confirmation).'=>'Доказ да је производ испоручен (нпр. потписана потврда о испоруци).','Documentation for the prior charge a duplicate dispute refers to.'=>'Документација за претходно задужење на које се односи спор о двоструком задужењу.','Your refund policy as shown to the customer.'=>'Ваша политика рефундације онако како је приказана купцу.','Receipt or message sent to the customer for the charge.'=>'Признаница или порука послата купцу за задужење.','Proof the customer signed for the product or agreed to terms.'=>'Доказ да је купац потписао пријем производа или прихватио услове.','Address the product was shipped to.'=>'Адреса на коју је производ послат.','Correspondence with the customer relevant to the dispute (e.g. emails).'=>'Преписка са купцем релевантна за спор (нпр. е-поруке).','Tracking number for a shipped physical product.'=>'Број за праћење послатог физичког производа.','Date the product was shipped.'=>'Датум слања производа.','Delivery service that shipped the product (e.g. USPS, FedEx, UPS, DHL).'=>'Служба доставе која је послала производ (нпр. USPS, FedEx, UPS, DHL).','Any additional explanation that does not fit another field.'=>'Свако додатно објашњење које не одговара другом пољу.','Activity log showing the customer accessed or downloaded a digital product.'=>'Дневник активности који показује да је купац приступио дигиталном производу или га преузео.','Explanation of why the customer was not entitled to cancel.'=>'Објашњење зашто купац није имао право на отказивање.','IP address the customer used for the purchase.'=>'IP адреса коју је купац користио за куповину.','Description of the product or service and how it was presented to the customer.'=>'Опис производа или услуге и начина на који је представљен купцу.','Required. A stable, caller-unique key so duplicate retries dedupe to the original refund instead of creating a second one. Reuse the exact same key when retrying the same logical refund.'=>'Обавезно. Стабилан кључ, јединствен за позиваоца, тако да се удвостручени поновни покушаји сведу на изворну рефундацију уместо да направе другу. Користите потпуно исти кључ при поновном покушају исте логичке рефундације.','A charge_id is required to create a refund.'=>'За прављење рефундације потребан је charge_id.','An idempotency_key is required so refund retries are safe.'=>'Потребан је idempotency_key да би поновни покушаји рефундације били безбедни.','Amount to refund in minor units (e.g. cents). Omit for a full refund.'=>'Износ за рефундацију у мањим јединицама (нпр. центима). Изоставите за потпуну рефундацију.','Optional refund reason.'=>'Необавезан разлог рефундације.','Stripe charge ID to refund (ch_… or py_…).'=>'Stripe ИБ задужења за рефундацију (ch_… или py_…).','Create a full or partial refund on a Stripe charge. Supply a stable idempotency_key to make retries safe — identical keys return the original refund. Amount is in minor units (e.g. cents).'=>'Направите потпуну или делимичну рефундацију за Stripe задужење. Наведите стабилан idempotency_key да би поновни покушаји били безбедни — исти кључеви враћају изворну рефундацију. Износ је у мањим јединицама (нпр. центима).','Refund a charge'=>'Рефундирај задужење','Return aggregate counts and totals for a transactions filter. Answers \'how many transactions / how much volume in this window?\' without paging the list.'=>'Враћа збирне бројеве и укупне износе за филтер трансакција. Одговара на питање „колико трансакција / колики обим у овом периоду?“ без страничења списка.','Get transactions summary'=>'Преузми сажетак трансакција','List WooPayments transactions with filters (date range, type, source device, channel, customer country, risk level, currency, search). Answers \'show me transactions where X\'.'=>'Приказује WooPayments трансакције са филтерима (опсег датума, врста, изворни уређај, канал, држава купца, ниво ризика, валута, претрага). Одговара на „прикажи ми трансакције где је X“.','List transactions'=>'Прикажи трансакције','A non-empty `intention_id` is required.'=>'Потребан је `intention_id` који није празан.','Return the chronological event timeline for a payment intent (created → succeeded → refunded → disputed). Helps reconstruct what happened to one transaction. Takes `intention_id` (the same Stripe `pi_…` identifier accepted by `get-payment-intent` as `payment_intent_id` — both names exist because they mirror the underlying REST route parameters).'=>'Враћа хронолошки ток догађаја за намеру плаћања (направљено → успело → рефундирано → оспорено). Помаже да се реконструише шта се десило са једном трансакцијом. Прима `intention_id` (исти Stripe `pi_…` идентификатор који `get-payment-intent` прихвата као `payment_intent_id` — оба имена постоје јер одражавају параметре основне REST путање).','A non-empty `payment_intent_id` is required.'=>'Потребан је `payment_intent_id` који није празан.','Get timeline for payment intent'=>'Преузми ток догађаја за намеру плаћања','Look up a single payment intent by Stripe ID (pi_…). Answers \'what is the state of intent pi_X?\' during incident response.'=>'Проналази једну намеру плаћања по Stripe ИБ-у (pi_…). Одговара на „какво је стање намере pi_X?“ током реаговања на инцидент.','Get payment intent by ID'=>'Преузми намеру плаћања по ИБ-у','A status is required to list fraud outcomes.'=>'За приказ исхода превара потребно је стање.','List transactions flagged by fraud protection for a given outcome status (e.g. block, review).'=>'Приказује трансакције које је заштита од превара означила за дато стање исхода (нпр. block, review).','List flagged (fraud outcome) transactions'=>'Прикажи означене трансакције (исход превара)','Return aggregate processing-fee totals (count, fees, net) over a date range. Answers \'how much did I pay in fees this period?\'.'=>'Враћа збирне укупне накнаде за обраду (број, накнаде, нето) за опсег датума. Одговара на „колико је плаћено накнада у овом периоду?“.','Fraud outcome status to filter by (e.g. block, review).'=>'Стање исхода превара по коме се филтрира (нпр. block, review).','Get processing-fee summary'=>'Преузми сажетак накнада за обраду','Return aggregate counts of disputes by status. Answers \'how many disputes are pending response right now?\'.'=>'Враћа збирне бројеве спорова по стању. Одговара на „колико спорова тренутно чека одговор?“.','Get disputes summary'=>'Преузми сажетак спорова','List disputes with status and date-range filters. Answers \'which disputes need response?\'.'=>'Приказује спорове са филтерима стања и опсега датума. Одговара на „којим споровима је потребан одговор?“.','List disputes'=>'Прикажи спорове','A non-empty `dispute_id` is required.'=>'Потребан је `dispute_id` који није празан.','Get dispute by ID'=>'Преузми спор по ИБ-у','Look up a single dispute by ID. Answers \'what evidence is needed for dispute du_X and by when?\'.'=>'Проналази један спор по ИБ-у. Одговара на „који докази су потребни за спор du_X и до када?“.','Return aggregate counts and totals of payouts by status and currency. Answers \'how many payouts have I received this month?\'.'=>'Враћа збирне бројеве и укупне износе исплата по стању и валути. Одговара на „колико исплата је примљено овог месеца?“.','Get payouts summary'=>'Преузми сажетак исплата','Return a per-currency overview of upcoming and recent payouts (Stripe deposits). Answers \'when is my next payout and how much?\'.'=>'Враћа преглед предстојећих и недавних исплата (Stripe уплата) по валути. Одговара на „када је моја следећа исплата и колика је?“.','Get payouts overview'=>'Преузми преглед исплата','List payouts (Stripe deposits) with status, date-range, and currency filters. Answers \'show me my recent payouts\'.'=>'Приказује исплате (Stripe уплате) са филтерима стања, опсега датума и валуте. Одговара на „прикажи ми недавне исплате“.','List payouts'=>'Прикажи исплате','A non-empty `charge_id` is required.'=>'Потребан је `charge_id` који није празан.','Look up a single charge by Stripe ID (ch_… or py_…). Answers \'what happened with charge ch_X?\'.'=>'Проналази једно задужење по Stripe ИБ-у (ch_… или py_…). Одговара на „шта се десило са задужењем ch_X?“.','Get charge by ID'=>'Преузми задужење по ИБ-у','A %s is required to read the balance summary.'=>'За читање сажетка стања потребан је %s.','Three-letter ISO-4217 currency code.'=>'Трословни ISO-4217 код валуте.','Start of the period (ISO-8601 date-time).'=>'Почетак периода (ISO-8601 датум и време).','End of the period (ISO-8601 date-time).'=>'Крај периода (ISO-8601 датум и време).','Return the balance summary (charges, refunds, disputes, fees, payouts, ending balance) for a currency over a date range.'=>'Враћа сажетак стања (задужења, рефундације, спорови, накнаде, исплате, завршно стање) за валуту у опсегу датума.','Return aggregate counts and total authorized amount for pending authorizations. Answers \'how much money is held in uncaptured authorizations?\'.'=>'Враћа збирне бројеве и укупан одобрени износ за одобрења на чекању. Одговара на „колико новца је задржано у ненаплаћеним одобрењима?“.','Get balance summary'=>'Преузми сажетак стања','Get authorizations summary'=>'Преузми сажетак одобрења','List uncaptured card authorizations. Answers \'which authorizations expire soon / still need capture?\'.'=>'Приказује ненаплаћена одобрења картица. Одговара на „која одобрења ускоро истичу / још треба наплатити?“.','List authorizations'=>'Прикажи одобрења','Return the merchant\'s active Stripe Capital loan summary. Answers \'how much do I still owe on my Capital loan and what is the daily repayment rate?\'. Returns an empty shape if no loan is active.'=>'Враћа сажетак активног Stripe Capital зајма трговца. Одговара на „колико још дугујем по Capital зајму и колика је дневна стопа отплате?“. Враћа празан облик ако нема активног зајма.','WooPayments is not initialized.'=>'WooPayments није покренут.','Return the merchant\'s WooPayments account state: onboarding status, country, store and customer currencies, KYC requirements, deadlines, and test/live mode flags.'=>'Враћа стање WooPayments налога трговца: стање почетног подешавања, државу, валуте продавнице и купаца, KYC захтеве, рокове и ознаке пробног/активног режима.','Get active Capital loan summary'=>'Преузми сажетак активног Capital зајма','Get WooPayments account state'=>'Преузми стање WooPayments налога','A dispute_id is required to accept a dispute.'=>'За прихватање спора потребан је dispute_id.','Stripe dispute ID (typically `du_…` or legacy `dp_…`). Stripe ID prefixes are not contractually stable, so this field is not pattern-validated.'=>'Stripe ИБ спора (обично `du_…` или застарело `dp_…`). Префикси Stripe ИБ-ова нису уговорно стабилни, па се ово поље не проверава по обрасцу.','Accept (concede) a dispute. The disputed funds are forfeited to the cardholder permanently. This cannot be undone.'=>'Прихватите (уступите) спор. Оспорена средства трајно се препуштају власнику картице. Ово не може да се опозове.','Maximum number of items per page.'=>'Највећи број ставки по страници.','Accept a dispute'=>'Прихвати спор','Maximum number of items requested per page.'=>'Највећи број ставки захтеван по страници.','Page number to return (1-indexed).'=>'Број странице за враћање (почиње од 1).','Current result page.'=>'Тренутна страница резултата.','Filter transactions where type matches any listed value.'=>'Филтрирај трансакције чија врста одговара било којој наведеној вредности.','Returned %s for the current page.'=>'Враћено %s за тренутну страницу.','Total number of result pages available for the current query.'=>'Укупан број страница резултата доступних за тренутни упит.','Search transactions by known identifiers.'=>'Претражи трансакције по познатим идентификаторима.','Currency must be an ISO 4217 three-letter code.'=>'Валута мора бити трословни ISO 4217 код.','Balance report currency.'=>'Валута извештаја о стању.','Express Checkout methods available for the cart\'s current currency.'=>'Начини брзог плаћања доступни за тренутну валуту корпе.','Balance report period start date.'=>'Датум почетка периода извештаја о стању.','Balance report period end date.'=>'Датум краја периода извештаја о стању.','The shipping address you selected requires a different currency (%2$s) than the one this payment was started with (%1$s). You have not been charged — please reload the page and try again.'=>'Адреса за доставу коју сте изабрали захтева другу валуту (%2$s) од оне којом је ово плаћање започето (%1$s). Нисте задужени — поново учитајте страницу и покушајте поново.','%s is not a valid currency code.'=>'%s није исправан код валуте.','%s is not a valid date-time value.'=>'%s није исправна вредност датума и времена.','A payment of %1$s <strong>failed</strong>: the saved payment method <strong>%2$s</strong> can no longer be used. A new payment method is required.'=>'Плаћање од %1$s <strong>није успело</strong>: сачувани начин плаћања <strong>%2$s</strong> више не може да се користи. Потребан је нови начин плаћања.','A test payment of %1$s was processed using %2$s in <strong>test mode</strong> (<a>%3$s</a>). No real funds were collected.'=>'Пробно плаћање од %1$s обрађено је помоћу %2$s у <strong>пробном режиму</strong> (<a>%3$s</a>). Нису наплаћена стварна средства.','A payment of %1$s <strong>failed</strong>: the saved payment method can no longer be used. A new payment method is required.'=>'Плаћање од %1$s <strong>није успело</strong>: сачувани начин плаћања више не може да се користи. Потребан је нови начин плаћања.','[Test] %s'=>'[Проба] %s','Invalid parameter(s): %s'=>'Неправилни параметри: %s','Dispute readiness is disabled.'=>'Припремљеност за спорове је искључена.','Reports'=>'Извештаји','Everything on the payments side is ready. The next step is getting your first customer through the door — share your store link and start spreading the word.'=>'Све на страни плаћања је спремно. Следећи корак је да доведете првог купца — поделите везу ка продавници и почните да ширите глас.','Your payments are ready — your first sale can be too'=>'Ваша плаћања су спремна — може бити и ваша прва продаја','Your account is fully approved and accepting payments. Share your store with your first potential customers to get that first sale.'=>'Ваш налог је потпуно одобрен и прима плаћања. Поделите своју продавницу са првим потенцијалним купцима да бисте остварили прву продају.','Two weeks in — have you shared your store yet?'=>'Две недеље касније — да ли сте већ поделили своју продавницу?','Your WooPayments account is approved and ready to accept payments. Now it’s about getting eyes on your store — share your link, tell your network, and make your first sale.'=>'Ваш WooPayments налог је одобрен и спреман за примање плаћања. Сада је важно да привучете пажњу на своју продавницу — поделите везу, реците својој мрежи и остварите прву продају.','Thanks for choosing WooPayments.'=>'Хвала што сте изабрали WooPayments.','Promote my store'=>'Промовиши моју продавницу','Your store is ready — let’s make your first sale'=>'Ваша продавница је спремна — хајде да остварите прву продају','Ready for your first sale on {site_title}?'=>'Спремни за прву продају на {site_title}?','We\'ll send a couple of reminders during your first month of accepting payments, to help you bring in your first sale. Stops automatically once you\'ve taken one.'=>'Послаћемо неколико подсетника током првог месеца примања плаћања, да бисмо вам помогли да остварите прву продају. Самостално престаје када је остварите.','First sale reminder'=>'Подсетник за прву продају','eftpos'=>'eftpos','Whether WooPayments is running in dev (sandbox) mode and what triggered it.'=>'Да ли WooPayments ради у развојном (sandbox) режиму и шта га је покренуло.','Dev Mode'=>'Развојни режим','WooPayments refunded its %s application fee on this transaction.'=>'WooPayments је рефундирао своју накнаду за апликацију од %s за ову трансакцију.','WooPayments refunded its application fee on this transaction.'=>'WooPayments је рефундирао своју накнаду за апликацију за ову трансакцију.','capped at %s'=>'ограничено на %s','Loan paydown'=>'Отплата зајма','Refund fee'=>'Накнада за рефундацију','Dispute fee refund'=>'Рефундација накнаде за спор','Tax on fee'=>'Порез на накнаду','Device fee'=>'Накнада за уређај','International card fee'=>'Накнада за међународну картицу','Subscription transaction fee'=>'Накнада за трансакцију претплате','Processing fee'=>'Накнада за обраду','%1$s: %2$s'=>'%1$s: %2$s','%1$s (%2$s): %3$s'=>'%1$s (%2$s): %3$s','Payment succeeded, but a downstream error occurred during post-payment processing: %s. Order status preserved.'=>'Плаћање је успело, али је дошло до грешке током обраде после плаћања: %s. Стање поруџбине је сачувано.','Terminal payments cannot be prepared for partially or fully refunded orders.'=>'Плаћања преко терминала не могу се припремити за делимично или потпуно рефундиране поруџбине.','Invalid payment intent ID.'=>'Неисправан ИБ намере плаћања.','Invalid appearance schema.'=>'Неисправна шема изгледа.','Missing or invalid appearance data.'=>'Недостају или су неисправни подаци о изгледу.','Price range: %1$s through %2$s'=>'Распон цена: од %1$s до %2$s','This action is not available.'=>'Ова радња није доступна.','You aren\'t authorized to do that.'=>'Немате овлашћење за то.','Current price is: %s.'=>'Тренутна цена је: %s.','Original price was: %s.'=>'Оригинална цена је била: %s.','Your card has insufficient funds.'=>'На вашој картици нема довољно средстава.','We are unable to authenticate your payment method. Please choose a different payment method and try again.'=>'Не можемо да проверимо ваш начин плаћања. Изаберите други начин плаћања и покушајте поново.','Your card was declined because additional authentication is required. Please contact your card issuer or try a different payment method.'=>'Ваша картица је одбијена јер је потребна додатна провера идентитета. Обратите се издаваоцу картице или покушајте другим начином плаћања.','Invalid wallet payment type, please try again or use an alternative method.'=>'Неисправна врста плаћања новчаником, покушајте поново или користите други начин.','Invalid Tax ID, please try again with a valid tax ID.'=>'Неисправан порески ИБ, покушајте поново са исправним пореским ИБ-ом.','Invalid country code, please try again with a valid country code.'=>'Неисправан код државе, покушајте поново са исправним кодом државе.','Invalid email address, please correct and try again.'=>'Неисправна е-адреса, исправите је и покушајте поново.','The billing country is not accepted by Sofort. Please try another country.'=>'Sofort не прихвата државу за наплату. Покушајте са другом државом.','An error occurred while processing your card. Try again in a little bit.'=>'Дошло је до грешке при обради ваше картице. Покушајте поново мало касније.','There is no card on a customer that is being charged.'=>'Купац коме се наплаћује нема картицу.','Your card was declined.'=>'Ваша картица је одбијена.','Your card\'s expiration year is in the past.'=>'Година истека ваше картице је у прошлости.','Invalid zip code, please correct and try again.'=>'Неисправан поштански број, исправите га и покушајте поново.','Your card has expired.'=>'Ваша картица је истекла.','Your card\'s expiration date is incomplete.'=>'Датум истека ваше картице није потпун.','Your card\'s security code is incorrect.'=>'Сигурносни кôд ваше картице није тачан.','Your card\'s security code is incomplete.'=>'Сигурносни кôд ваше картице није потпун.','Your card number is incomplete.'=>'Број ваше картице није потпун.','Your card number is incorrect.'=>'Број ваше картице није тачан.','Your card\'s expiration year is invalid.'=>'Година истека ваше картице није исправна.','Your card\'s security code is invalid.'=>'Сигурносни кôд ваше картице није исправан.','Your card\'s expiration month is invalid.'=>'Месец истека ваше картице није исправан.','The card number is not a valid credit card number.'=>'Број картице није исправан број кредитне картице.','WooPayments styles cleared'=>'WooPayments стилови су очишћени','This tool will clear the styles cached for the WooPayments gateway UI elements at checkout'=>'Ова алатка ће очистити кеширане стилове за елементе интерфејса WooPayments платног пролаза при плаћању','Clear WooPayments calculated styles'=>'Очисти израчунате WooPayments стилове','Payment method is changed to: <strong>Link ending in %1$s</strong>.'=>'Начин плаћања је промењен у: <strong>Link који се завршава на %1$s</strong>.','iDEAL | Wero'=>'iDEAL | Wero','%1$s (%2$s)'=>'%1$s (%2$s)','The support phone number set in WooPayments settings. If not set, the settings Save button will be disabled.'=>'Телефон подршке постављен у WooPayments подешавањима. Ако није постављен, дугме за чување подешавања биће искључено.','Not set'=>'Није подешено','Support Phone'=>'Телефон подршке','Amazon Pay (%s)'=>'Amazon Pay (%s)','A payment of %1$s was successfully charged using %2$s (%3$s).'=>'Плаћање од %1$s успешно је наплаћено помоћу %2$s (%3$s).','Unable to save payment method for subscription. Please try again or use a different payment method.'=>'Није могуће сачувати начин плаћања за претплату. Покушајте поново или користите други начин плаћања.','If express checkout methods (Apple Pay, Google Pay, Amazon Pay) should be enabled as options in the payment methods list.'=>'Да ли начине брзог плаћања (Apple Pay, Google Pay, Amazon Pay) треба укључити као могућности на списку начина плаћања.','Test mode is active because your store is running in a development or staging environment. To disable it, switch to a production %1$sWordPress environment%2$s or remove the WCPAY_DEV_MODE constant. %3$sLearn more%4$s'=>'Пробни режим је активан јер ваша продавница ради у развојном или пробном окружењу. Да бисте га искључили, пређите на производно %1$sВордпрес окружење%2$s или уклоните константу WCPAY_DEV_MODE. %3$sСазнајте више%4$s','A digital wallet for customers with mainland China WeChat Pay wallets. Regional versions like WeChat Pay HK are not supported.'=>'Дигитални новчаник за купце са WeChat Pay новчаницима из континенталне Кине. Регионална издања као што је WeChat Pay HK нису подржана.','A digital wallet for customers with mainland China Alipay accounts. Regional versions like AlipayHK are not supported.'=>'Дигитални новчаник за купце са Alipay налозима из континенталне Кине. Регионална издања као што је AlipayHK нису подржана.','Go to Tools page'=>'Иди на страницу алатки','Some orders with canceled payment authorizations have incorrect data that may cause negative values in your WooCommerce Analytics. This affects stores using manual capture (authorize and capture separately). Run the fix tool to correct this.'=>'Неке поруџбине са отказаним одобрењима плаћања имају нетачне податке који могу изазвати негативне вредности у WooCommerce аналитици. Ово погађа продавнице које користе ручну наплату (засебно одобрење и наплата). Покрените алатку за исправку да бисте ово исправили.','WooPayments: Fix incorrect order data'=>'WooPayments: исправи нетачне податке поруџбина','%s <strong>Status: Running...</strong> Check the Action Scheduler for details.'=>'%s <strong>Стање: ради...</strong> Погледајте Action Scheduler за детаље.','%1$s <strong>Status: Running...</strong> Processed %2$d orders so far. Check the Action Scheduler for details.'=>'%1$s <strong>Стање: ради...</strong> До сада је обрађено %2$d поруџбина. Погледајте Action Scheduler за детаље.','%s <strong>Status: Completed.</strong> No affected orders found.'=>'%s <strong>Стање: завршено.</strong> Нису пронађене погођене поруџбине.','%1$s <strong>Status: Completed.</strong> Processed %2$d orders, remediated %3$d.'=>'%1$s <strong>Стање: завршено.</strong> Обрађено је %2$d поруџбина, исправљено %3$d.','This tool removes incorrect refund records and fee data from orders where payment authorization was canceled (not captured). This fixes negative values appearing in WooCommerce Analytics for stores using manual capture.'=>'Ова алатка уклања нетачне записе о рефундацијама и податке о накнадама из поруџбина у којима је одобрење плаћања отказано (није наплаћено). Тиме се исправљају негативне вредности у WooCommerce аналитици за продавнице које користе ручну наплату.','Run'=>'Покрени','Running...'=>'Ради...','Error scheduling dry run: %s'=>'Грешка при заказивању пробног покретања: %s','Dry run has been scheduled and will run in the background. Check WooCommerce > Status > Logs for results (source: wcpay-fee-remediation).'=>'Пробно покретање је заказано и радиће у позадини. Резултате погледајте у WooCommerce > Status > Logs (извор: wcpay-fee-remediation).','Error scheduling remediation: %s'=>'Грешка при заказивању исправке: %s','Remediation has been scheduled and will run in the background. You can monitor progress in the Action Scheduler.'=>'Исправка је заказана и радиће у позадини. Напредак можете пратити у Action Scheduler-у.','Remediation has already been completed.'=>'Исправка је већ завршена.','Remediation is already in progress. Check the Action Scheduler for status.'=>'Исправка је већ у току. Стање погледајте у Action Scheduler-у.','You do not have permission to run this tool.'=>'Немате дозволу да покренете ову алатку.','This will update order metadata and delete incorrect refund records for affected orders. This fixes negative values in WooCommerce Analytics. Make sure you have a recent backup before proceeding. Continue?'=>'Ово ће ажурирати метаподатке поруџбина и избрисати нетачне записе о рефундацијама за погођене поруџбине. Тиме се исправљају негативне вредности у WooCommerce аналитици. Уверите се да имате недавну резервну копију пре него што наставите. Наставити?','Fix canceled authorization analytics'=>'Исправи аналитику отказаних одобрења','Preview what orders would be affected by the canceled authorization fix without making any changes. Results are logged to WooCommerce > Status > Logs.'=>'Прегледајте које би поруџбине биле погођене исправком отказаних одобрења без икаквих измена. Резултати се бележе у WooCommerce > Status > Logs.','Error: Communications email is required.'=>'Грешка: е-адреса за комуникацију је обавезна.','Invalid value type; expected %s'=>'Неисправна врста вредности; очекивано %s','Preview canceled authorization fix (Dry Run)'=>'Преглед исправке отказаних одобрења (пробно покретање)','Email address used for WooPayments communications.'=>'Е-адреса која се користи за WooPayments комуникацију.','WooPay checkout encountered a fatal error: %s'=>'WooPay плаћање је наишло на кобну грешку: %s','Please select a customer first'=>'Прво изаберите купца','Offer customers a fast, secure checkout experience with Amazon Pay.'=>'Понудите купцима брзо и безбедно плаћање уз Amazon Pay.','Allow customers to pay over time with Cash App Afterpay.'=>'Омогућите купцима да плаћају на рате уз Cash App Afterpay.','No payment methods found for customer'=>'Нису пронађени начини плаћања за купца','Invalid user ID.'=>'Неисправан ID корисника.','Payment token with wallet%1$s %2$s'=>'%1$s %2$s','Express checkout methods on checkout page'=>'Начини брзог плаћања на страници плаћања','You do not have permission to perform this action.'=>'Немате овлашћење да извршите ову радњу.','Express checkout methods on cart page'=>'Начини брзог плаћања на страници корпе','Express checkout methods on product page'=>'Начини брзог плаћања на страници производа','This order was already paid for %1$s, but the order total has since changed to %2$s, so we prevented an overpayment. Please create a new order for any additional items.'=>'Ова поруџбина је већ плаћена у износу од %1$s, али се укупан износ поруџбине у међувремену променио на %2$s, па смо спречили преплату. Направите нову поруџбину за све додатне ставке.','Express checkout methods enabled on product page.'=>'Начини брзог плаћања укључени су на страници производа.','Express checkout methods enabled on cart page.'=>'Начини брзог плаћања укључени су на страници корпе.','Express checkout methods enabled on checkout page.'=>'Начини брзог плаћања укључени су на страници плаћања.','Amazon Pay'=>'Amazon Pay','Non-compliant'=>'Неусклађено','Subscription set to manual renewal because %s is a non-reusable payment method.'=>'Претплата је постављена на ручну обнову јер је %s начин плаћања који се не може поново користити.','See terms'=>'Погледај услове','The promotion unique identifier.'=>'Јединствени идентификатор промоције.','Subscription products cannot be added to orders. Please install WooCommerce Subscriptions to manage subscriptions.'=>'Производи претплате не могу се додати у поруџбине. Поставите WooCommerce Subscriptions да бисте управљали претплатама.','To access your subscriptions data and keep managing recurring payments, please install <a target="_blank" href="%1$s">WooCommerce Subscriptions</a>. Built-in support for subscriptions is no longer available in WooPayments.'=>'Да бисте приступили подацима о претплатама и наставили да управљате понављајућим плаћањима, поставите <a target="_blank" href="%1$s">WooCommerce Subscriptions</a>. Уграђена подршка за претплате више није доступна у WooPayments-у.','%s has been removed from your cart because it can no longer be purchased. Please contact us if you need assistance.'=>'%s је уклоњен из ваше корпе јер више не може бити купљен. Контактирајте нас ако вам је потребна помоћ.','Built-in subscriptions functionality has been removed. Here\'s what to do'=>'Уграђена функционалност претплата је уклоњена. Ево шта треба да урадите','%d test order has been permanently deleted.'=>'%d пробна поруџбина је трајно избрисана.' . "\0" . '%d пробне поруџбине су трајно избрисане.' . "\0" . '%d пробних поруџбина је трајно избрисано.','To continue offering subscriptions and gain access to your data, please install WooCommerce Subscriptions. WooPayments no longer supports this feature.'=>'Да бисте наставили да нудите претплате и добили приступ својим подацима, поставите WooCommerce Subscriptions. WooPayments више не подржава ову функцију.','Error deleting test orders: %s'=>'Грешка при брисању пробних поруџбина: %s','No test orders found.'=>'Нису пронађене пробне поруџбине.','You do not have permission to delete orders.'=>'Немате дозволу да бришете поруџбине.','<strong class="red">Note:</strong> This option deletes all test mode orders placed via %s. Orders placed via other gateways will not be affected. Use with caution, as this action cannot be undone.'=>'<strong class="red">Напомена:</strong> Ова могућност брише све поруџбине у пробном режиму направљене преко %s. Поруџбине направљене преко других платних пролаза неће бити погођене. Користите опрезно, јер се ова радња не може опозвати.','Delete %s test orders'=>'Избриши %s пробне поруџбине','You are using a sandbox test account.'=>'Користите пробни налог у sandbox окружењу.','To begin accepting real payments, please go to the live store or change your %1$sWordPress environment%2$s to a production one. %3$sLearn more%4$s'=>'Да бисте почели да примате стварна плаћања, идите на активну продавницу или промените своје %1$sВордпрес окружење%2$s у производно. %3$sСазнајте више%4$s','By proceeding with your purchase you agree to our %1$s and %2$s'=>'Наставком куповине прихватате наше %1$s и %2$s','To begin accepting real payments you will need to first %1$sreset your account%2$s and, then, provide additional details about your business. %3$sLearn more%4$s'=>'Да бисте почели да примате стварна плаћања, прво морате %1$sпоништити свој налог%2$s, а затим пружити додатне детаље о свом пословању. %3$sСазнајте више%4$s','⚠️ Development mode is enabled for the store! There can be no live onboarding process while using development, testing, or staging WordPress environments!'=>'⚠️ За продавницу је укључен развојни режим! Не може постојати стварни поступак почетног подешавања док се користе развојна, тестна или пробна Вордпрес окружења!','Provide additional details about your business so you can begin accepting real payments. %1$sLearn more%2$s'=>'Пружите додатне детаље о свом пословању да бисте почели да примате стварна плаћања. %1$sСазнајте више%2$s','You can use %1$stest card numbers%2$s to simulate various types of transactions.'=>'Можете користити %1$sпробне бројеве картица%2$s за симулацију различитих врста трансакција.','%s is in test mode — all transactions are simulated!'=>'%s је у пробном режиму — све трансакције се симулирају!','Card'=>'Картица','You are using a test account.'=>'Користите пробни налог.','WooPayments no longer supports subscriptions capabilities and subscriptions data can no longer be accessed. Please install <a target="_blank" href="%1$s">WooCommerce Subscriptions</a> to continue managing your subscriptions.'=>'WooPayments више не подржава могућности претплата и подацима о претплатама више се не може приступити. Поставите <a target="_blank" href="%1$s">WooCommerce Subscriptions</a> да бисте наставили да управљате претплатама.','WooPayments no longer supports billing for existing customer subscriptions. All subscriptions data is read-only. Please install <a target="_blank" href="%1$s">WooCommerce Subscriptions</a> to continue managing your subscriptions.'=>'WooPayments више не подржава наплату постојећих претплата купаца. Сви подаци о претплатама су само за читање. Поставите <a target="_blank" href="%1$s">WooCommerce Subscriptions</a> да бисте наставили да управљате претплатама.','WooPayments no longer allows customers to create new subscriptions. Beginning in version 9.8, billing for existing customer subscriptions will no longer be supported. To ensure there is no interruption of service, please install <a target="_blank" href="%1$s">WooCommerce Subscriptions</a>.'=>'WooPayments више не дозвољава купцима да праве нове претплате. Од издања 9.8 наплата постојећих претплата купаца више неће бити подржана. Да не би дошло до прекида услуге, поставите <a target="_blank" href="%1$s">WooCommerce Subscriptions</a>.','NO VAT'=>'БЕЗ ПДВ-а','Install WooCommerce Subscriptions'=>'Постави WooCommerce Subscriptions','<strong>Important:</strong> From version 9.7 of WooPayments (scheduled for 23 July, 2025), you\'ll <strong>no longer be able to offer new product subscriptions</strong>. To avoid disruption, please install <a target="_blank" href="%1$s">WooCommerce Subscriptions</a>.'=>'<strong>Важно:</strong> Од издања 9.7 WooPayments-а (заказаног за 23. јул 2025.) <strong>више нећете моћи да нудите нове претплате на производе</strong>. Да бисте избегли прекид, поставите <a target="_blank" href="%1$s">WooCommerce Subscriptions</a>.','Failed to reset the account: account does not exist.'=>'Поништавање налога није успело: налог не постоји.','Failed to activate the account: account does not exist.'=>'Укључивање налога није успело: налог не постоји.','Tax%1$s%2$s: %3$s'=>'Порез%1$s%2$s: %3$s','JP JCT'=>'JP JCT','CH VAT'=>'CH VAT','NZ GST'=>'NZ GST','SG GST'=>'SG GST','AU GST'=>'AU GST','SK VAT'=>'SK VAT','SI VAT'=>'SI VAT','SE VAT'=>'SE VAT','RO VAT'=>'RO VAT','PL VAT'=>'PL VAT','PT VAT'=>'PT VAT','NL VAT'=>'NL VAT','MT VAT'=>'MT VAT','LV VAT'=>'LV VAT','LU VAT'=>'LU VAT','IE VAT'=>'IE VAT','IT VAT'=>'IT VAT','LT VAT'=>'LT VAT','HR VAT'=>'HR VAT','HU VAT'=>'HU VAT','GR VAT'=>'GR VAT','UK VAT'=>'UK VAT','FR VAT'=>'FR VAT','FI VAT'=>'FI VAT','ES VAT'=>'ES VAT','EE VAT'=>'EE VAT','DK VAT'=>'DK VAT','DE VAT'=>'DE VAT','CZ VAT'=>'CZ VAT','CY VAT'=>'CY VAT','BG VAT'=>'BG VAT','BE VAT'=>'BE VAT','AT VAT'=>'AT VAT','Your store is not connected to WordPress.com. Please connect it first.'=>'Ваша продавница није повезана са WordPress.com. Прво је повежите.','Onboarding initialization is already in progress. Please wait for it to finish.'=>'Покретање почетног подешавања је већ у току. Сачекајте да се заврши.','You cannot add a new payment method so soon after the previous one. Please try again later.'=>'Не можете додати нови начин плаћања тако брзо после претходног. Покушајте поново касније.','WooPayments woopay order status sync'=>'WooPayments усклађивање стања woopay поруџбина','Payment for the order failed with the following message: "%1$s" and failure code <code>%2$s</code>'=>'Плаћање поруџбине није успело уз следећу поруку: „%1$s“ и код грешке <code>%2$s</code>','The refund was canceled at your request.'=>'Рефундација је отказана на ваш захтев.','An unknown error occurred while processing the refund.'=>'Дошло је до непознате грешке при обради рефундације.','The refund was declined by the card issuer.'=>'Издавалац картице